var n=`1259-bajan-cou-cou`;var t=`world-1259`;var a=`BB`;var r=`central-america-caribbean`;var o=4;var s=41;var u={en:`Bajan Cou-Cou`,ua:`Барбадоська кукурудзяна каша куку`};var l={en:`Bajan Cou-Cou is a dish from Barbados featuring okra, cornmeal. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Барбадоська кукурудзяна каша куку, страва кухні країни Барбадос з такими основними складниками: бамія, кукурудзяна крупа дрібного помелу. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var m=[{en:`Cook the listed ingredients in simmering water for about 17 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 17 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:17,i:[[`okra`,340,`g`],[`water`,680,`ml`]]},{en:`Gradually stir cornmeal into the hot okra liquid, whisking continuously so no lumps remain; cook to a thick, smooth cou-cou.`,ua:`Поступово всипайте кукурудзяне борошно в гарячий відвар окри, постійно помішуючи без грудочок; приготуйте густе гладке куку.`,t:[`mixing`],m:8,i:[[`cornmeal`,370,`g`],[`water`,680,`ml`],[`unsalted-butter`,35,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 13 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 13 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:13,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,3,`g`]]}];var d={slug:n,id:t,country:`BB`,region:r,servings:4,minutes:41,title:u,text:l,steps:m};export{a as country,d as default,t as id,s as minutes,r as region,o as servings,n as slug,m as steps,l as text,u as title};